package com.nivor.health;
import com.nivor.common.exception.ResourceNotFoundException;import com.nivor.health.HealthDtos.*;import com.nivor.user.UserService;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class HealthRecordService{private final HealthRecordRepository repo;private final UserService users;public HealthRecordService(HealthRecordRepository r,UserService u){repo=r;users=u;}public List<RecordView> list(String email,LocalDate from,LocalDate to){if(from==null)from=LocalDate.now().minusDays(29);if(to==null)to=LocalDate.now();if(to.isBefore(from))throw new IllegalArgumentException("End date must not precede start date");return repo.findAllByUser_IdAndDateBetweenOrderByDateDesc(uid(email),from,to).stream().limit(366).map(RecordView::from).toList();}public RecordView get(String e,long id){return RecordView.from(owned(e,id));}public RecordView create(String e,RecordRequest r){HealthRecord x=repo.findByUser_IdAndDate(uid(e),r.date()).orElseGet(HealthRecord::new);x.setUser(users.getByEmail(e));apply(x,r);return RecordView.from(repo.save(x));}public RecordView update(String e,long id,RecordRequest r){HealthRecord x=owned(e,id);apply(x,r);return RecordView.from(x);}public void delete(String e,long id){repo.delete(owned(e,id));}public Summary summary(String e){List<HealthRecord> xs=repo.findAllByUser_IdAndDateBetweenOrderByDateDesc(uid(e),LocalDate.now().minusDays(6),LocalDate.now());HealthRecord latest=xs.stream().filter(x->x.getWeight()!=null).findFirst().orElse(null);return new Summary(latest==null?null:latest.getWeight(),avg(xs,HealthRecord::getSleepMinutes),avg(xs,HealthRecord::getWaterMl),avg(xs,HealthRecord::getSteps),xs.stream().map(HealthRecord::getExerciseMinutes).filter(Objects::nonNull).mapToInt(Integer::intValue).sum(),xs.size());}private Double avg(List<HealthRecord> xs,java.util.function.Function<HealthRecord,Integer> f){return xs.stream().map(f).filter(Objects::nonNull).mapToInt(Integer::intValue).average().orElse(0);}private long uid(String e){return users.getByEmail(e).getId();}private HealthRecord owned(String e,long id){return repo.findByIdAndUser_Id(id,uid(e)).orElseThrow(()->new ResourceNotFoundException("Health record not found"));}private void apply(HealthRecord x,RecordRequest r){x.setDate(r.date());x.setWeight(r.weight());x.setWaterMl(r.waterMl());x.setSleepMinutes(r.sleepMinutes());x.setSteps(r.steps());x.setExerciseMinutes(r.exerciseMinutes());x.setNotes(r.notes());}}
